CREATE TABLE DBP_MSI_DATA.TUPEL_MAT_FORECAST (
   id                                  VARCHAR(50)     NOT NULL COMMENT 'Unique Forecast ID',
   mandant_id                          NUMBER(38,0)    NOT NULL COMMENT 'Country',
   a500_kjwo_update                    NUMBER(38,0)    NOT NULL COMMENT 'week definition of Sortimentstool',
   matching_id                         NUMBER(38,0)    NOT NULL COMMENT 'Tupel identifier',
   a51_listung_sst_pflege              NUMBER(2,0)     COMMENT 'Setting of SST-Listung from Enduser',
   a52_listung_k_sst_pflege            VARCHAR(4)      COLLATE 'en-ci' COMMENT 'Setting of KSST-Listung from Enduser',
   a426_ost_basis_pflege               VARCHAR(4)      COLLATE 'en-ci' COMMENT 'Setting of Ost Basis Listung from Enduser',
   a427_ost_gross_pflege               VARCHAR(4)      COLLATE 'en-ci' COMMENT 'Setting of Ost gross Listung from Enduser',
   a428_sued_ost_pflege                VARCHAR(4)      COLLATE 'en-ci' COMMENT 'Setting of Sued-Ost Listung from Enduser',
   a429_sued_west_pflege               VARCHAR(4)      COLLATE 'en-ci' COMMENT 'Setting of Sued-West Listung from Enduser',
   a430_west_pflege                    VARCHAR(4)      COLLATE 'en-ci' COMMENT 'Setting of West Listung from Enduser',
   a431_nord_pflege                    VARCHAR(4)      COLLATE 'en-ci' COMMENT 'Setting of Nord Listung from Enduser',
   a411_stk_rohertrag_pflege           NUMBER(18,4)    COMMENT 'Setting of Rohertrag Stueck from Enduser',
   a412_umsatz_brutto_hochrechnung     NUMBER(18,4)    COMMENT 'Forecast Umsatz',
   a413_absatz_hochrechnung            NUMBER(18,4)    COMMENT 'Forecast Absatz',
   a414_rohertrag_hochrechnung         NUMBER(18,4)    COMMENT 'Forecast Rohertrag (A413_ABSATZ_HOCHRECHNUNG x A411_STK_ROHERTRAG_PFLEGE)',
   a415_kannibalisierungsfaktor        NUMBER(18,4)    COMMENT 'Factor for Forecasts from Enduser',
   a50_listungsaktion                  VARCHAR(255)    COLLATE 'en-ci' COMMENT 'Impact of Forecast',
   listing_proposal_pflege             VARCHAR(255)    COLLATE 'en-ci' COMMENT 'Input field from Enduser',
   execution_timestamp                 TIMESTAMP_LTZ(9) COMMENT 'Timestamp of row creation done by Service Layer',
   TD_UPDATE 	TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
   TD_INSERT 	TIMESTAMP_LTZ(9) COMMENT 'Technical fields for synchronisation framework. Will be delted after last product migration',
   CONSTRAINT PK_TUPEL_MAT_FORECAST PRIMARY KEY (id) NOT ENFORCED
)  COMMENT = 'Forecast Sortimentstool filled by Service Layer';
